// AES-256-GCM encryption for secrets stored in app_settings (§2 invariant 7).
//
// Key = PORTFOLIO_ENCRYPTION_KEY (32-byte base64), generated by the setup
// wizard if missing. Stored ciphertext format:  `v1:<iv>:<tag>:<data>`  where
// iv/tag/data are base64. The `v1:` prefix lets us change the format later
// without a blind re-encrypt.
//
// Losing the key makes every encrypted app_settings value unrecoverable; the
// wizard and README both say so loudly.
//
// This module never logs plaintext or the key, and maskSecret() is the only
// shape in which a saved secret may be returned to the browser.

import { createCipheriv, createDecipheriv, randomBytes } from 'node:crypto';

const ALGO = 'aes-256-gcm';
const IV_LEN = 12;
const TAG_LEN = 16;
const KEY_LEN = 32;
const PREFIX = 'v1';

export function generateEncryptionKey(): string {
  return randomBytes(KEY_LEN).toString('base64');
}

function decodeKey(keyB64: string): Buffer {
  const buf = Buffer.from(keyB64, 'base64');
  if (buf.length !== KEY_LEN) {
    throw new Error(
      `PORTFOLIO_ENCRYPTION_KEY must decode to ${KEY_LEN} bytes, got ${buf.length}. Generate one with: openssl rand -base64 32`,
    );
  }
  return buf;
}

export function encrypt(plaintext: string, keyB64: string): string {
  const key = decodeKey(keyB64);
  const iv = randomBytes(IV_LEN);
  const cipher = createCipheriv(ALGO, key, iv);
  const enc = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
  const tag = cipher.getAuthTag();
  return [PREFIX, iv.toString('base64'), tag.toString('base64'), enc.toString('base64')].join(':');
}

export function decrypt(stored: string, keyB64: string): string {
  if (!stored.startsWith(PREFIX + ':')) {
    throw new Error('Unsupported ciphertext (expected v1 prefix)');
  }
  const parts = stored.split(':');
  if (parts.length !== 4) {
    throw new Error('Malformed ciphertext');
  }
  const ivB64 = parts[1];
  const tagB64 = parts[2];
  const dataB64 = parts[3];
  if (ivB64 === undefined || tagB64 === undefined || dataB64 === undefined) {
    throw new Error('Malformed ciphertext');
  }
  const key = decodeKey(keyB64);
  const iv = Buffer.from(ivB64, 'base64');
  const tag = Buffer.from(tagB64, 'base64');
  if (iv.length !== IV_LEN || tag.length !== TAG_LEN) {
    throw new Error('Malformed ciphertext (iv/tag length)');
  }
  const data = Buffer.from(dataB64, 'base64');
  const decipher = createDecipheriv(ALGO, key, iv);
  decipher.setAuthTag(tag);
  const dec = Buffer.concat([decipher.update(data), decipher.final()]);
  return dec.toString('utf8');
}

// The only shape in which a saved secret may be returned to the browser after
// save (§2 invariant 7): "••••" + last 4 chars. Never the full value.
export function maskSecret(value: string): string {
  if (!value) return '';
  return `••••${value.slice(-4)}`;
}
